def solve(xs: list[int]) -> int:
    count = 0
    n = len(xs)
    for i in range(n):
        for j in range(i + 1, n):
            if xs[i] > xs[j] and (xs[i] - xs[j]) % 2 == 0:
                count += 1
    return count

def solve(xs: list[int]) -> int:
    if not xs:
        return 0
    if all(x == xs[0] for x in xs):
        return sum(xs)
    has_odd = any(x % 2 != 0 for x in xs)
    has_even = any(x % 2 == 0 for x in xs)
    if has_odd:
        return 2
    if has_even:
        return 1
    return 0
